#!/usr/bin/env node
/* Targeted bundle rebuild for the store-entrypoints work (2026-10-08).
 * WHY: build/bundle.js's unbundled-file gate FAILs on this branch (19 game
 * silos committed by sibling workers are not registered in SECTIONS — a
 * pre-existing branch condition, unrelated to this task). The gate runs
 * before any bundle is written, so a full `node build/bundle.js` cannot
 * complete here. This script reuses build/bundle.js's own SECTIONS mapping
 * (evaluated from the real file, not a copy) and its exact write logic
 * (raw fallback — terser is not installed, same as the real build's
 * fallback path) for ONLY the bundles whose silos this task changed:
 *   bundle-fund (propaganda-fund.js)   /fund
 *   bundle-home (campaign.js)           homepage
 *   bundle-ventures (ventures.js)       /ventures
 *   bundle-cells (cell-war.js)          /cells
 *   bundle-sec1 (briefing.js)           homepage critical
 * Usage: node scripts/targeted-bundle-rebuild.js (from worktree root) */
'use strict';
var fs = require('fs');
var path = require('path');
var cp = require('child_process');

var ROOT_DIR = path.join(__dirname, '..');
var GAMES_ROOT = path.join(ROOT_DIR, 'site', 'v1.4.3', 'games');

/* Evaluate ONLY the SECTIONS literal out of build/bundle.js. */
var src = fs.readFileSync(path.join(ROOT_DIR, 'build', 'bundle.js'), 'utf8');
var start = src.indexOf('var SECTIONS = {');
if (start === -1) { console.error('SECTIONS not found'); process.exit(1); }
var end = src.indexOf('\n};', start);
if (end === -1) { console.error('SECTIONS end not found'); process.exit(1); }
var SECTIONS;
eval(src.slice(start, end + 3).replace(/^var SECTIONS/, 'SECTIONS')); // eslint-disable-line

var TARGETS = ['bundle-fund', 'bundle-home', 'bundle-ventures', 'bundle-cells', 'bundle-sec1'];

TARGETS.forEach(function (name) {
  var dest = path.join(GAMES_ROOT, name + '.js');
  /* File list from the checked-in bundle's own "Contains:" header — the
     last successfully-built list. SECTIONS in build/bundle.js may name
     files that don't exist on this branch (pre-existing sibling breakage,
     e.g. fred-ticker.js); the header list is the authoritative build input. */
  var header = fs.readFileSync(dest, 'utf8').match(/^   Contains: ([^\n]+)/m);
  if (!header) { console.error('no Contains header in ' + name); process.exit(1); }
  var files = header[1].split(/,\s*/);
  var out = [];
  out.push('/* PF v1.4.3 ' + name + '.js — concatenated bundle, generated by build/bundle.js.');
  out.push('   DO NOT EDIT. Regenerate with: node build/bundle.js [--debug]');
  out.push('   Contains: ' + files.join(', '));
  out.push('   Each silo keeps its own PF.skip() kill switch (?pf_off=<silo>). */');
  files.forEach(function (f) {
    var p = path.join(GAMES_ROOT, f);
    if (!fs.existsSync(p)) { console.error('missing file: ' + f); process.exit(1); }
    out.push('\n/* ===== ' + f + ' ===== */');
    out.push(fs.readFileSync(p, 'utf8'));
    /* Semicolon guard: ensure files can't bleed into each other. */
    out.push(';');
  });
  fs.writeFileSync(dest, out.join('\n'));
  try { cp.execSync(process.execPath + ' --check ' + dest, { stdio: 'pipe' }); }
  catch (e) { console.error(name + ' failed node --check'); process.exit(1); }
  console.log(name + '.js: ' + files.length + ' files — OK');
});
console.log('Targeted bundles rebuilt (raw mode; terser absent, same as build fallback).');
